<script>
    function checkStrength(val) {
      const hasLength = val.length >= 8;
      const hasUpper = /[A-Z]/.test(val);
      const hasSymbol = /[!@#$%^&*(),.?":{}|<>]/.test(val);

      updateCrit('critLength', hasLength);
      updateCrit('critUpper', hasUpper);
      updateCrit('critSymbol', hasSymbol);

      const score = (hasLength ? 1 : 0) + (hasUpper ? 1 : 0) + (hasSymbol ? 1 : 0);
      const bar = document.getElementById('strengthBar');
      const text = document.getElementById('strengthText');

      if (!val) {
        bar.className = 'h-full w-0 bg-outline transition-all duration-300';
        text.innerText = 'Not Evaluated';
        text.className = 'font-label-sm text-label-sm text-outline font-semibold';
      } else if (score === 1) {
        bar.className = 'h-full w-1/3 bg-error transition-all duration-300';
        text.innerText = 'Weak Security';
        text.className = 'font-label-sm text-label-sm text-error font-semibold';
      } else if (score === 2) {
        bar.className = 'h-full w-2/3 bg-secondary transition-all duration-300';
        text.innerText = 'Moderate Security';
        text.className = 'font-label-sm text-label-sm text-secondary font-semibold';
      } else {
        bar.className = 'h-full w-full bg-tertiary transition-all duration-300';
        text.innerText = 'Enterprise Grade';
        text.className = 'font-label-sm text-label-sm text-tertiary font-semibold';
      }
    }

    function updateCrit(elementId, passed) {
      const el = document.getElementById(elementId);
      if (!el) return;
      const icon = el.querySelector('.material-symbols-outlined');
      if (passed) {
        el.classList.remove('text-outline');
        el.classList.add('text-tertiary');
        if (icon) icon.innerText = 'check_circle';
      } else {
        el.classList.remove('text-tertiary');
        el.classList.add('text-outline');
        if (icon) icon.innerText = 'radio_button_unchecked';
      }
    }

    function validateMatch() {
      const pass = document.getElementById('password').value;
      const confirm = document.getElementById('confirmPassword').value;
      const confirmInput = document.getElementById('confirmPassword');
      if (confirm && pass !== confirm) {
        confirmInput.classList.add('text-error');
      } else {
        confirmInput.classList.remove('text-error');
      }
    }

    function togglePassVisibility(id, btn) {
      const input = document.getElementById(id);
      const icon = btn.querySelector('.material-symbols-outlined');
      if (input.type === 'password') {
        input.type = 'text';
        icon.innerText = 'visibility_off';
      } else {
        input.type = 'password';
        icon.innerText = 'visibility';
      }
    }

    function handleRegistration() {
      const btn = document.getElementById('submitBtn');
      btn.disabled = true;
      btn.innerHTML = `<span class="material-symbols-outlined animate-spin text-xl">progress_activity</span><span>Provisioning Isolated Database...</span>`;
      setTimeout(() => {
        btn.innerHTML = `<span class="material-symbols-outlined text-xl">check_circle</span><span>Portal Created! Redirecting...</span>`;
        btn.classList.remove('bg-primary');
        btn.classList.add('bg-tertiary');
        setTimeout(() => {
          window.location.href = "{{ route('admin.login') }}";
        }, 900);
      }, 1600);
    }
  </script>
